svg.script:
(function(){
  var sections = document.querySelectorAll('.sp-flow-section');
  var buttons = document.querySelectorAll('.sp-channel-btn');
  var reset = document.getElementById('sp-reset');

  function highlight(type) {
    var i, s, sec, j, b, p, active, bg;
    for (i = 0; i < sections.length; i++) {
      s = sections[i];
      sec = s.getAttribute('data-section');
      s.style.opacity = (!type || sec === type) ? '1' : '0.15';
    }
    for (j = 0; j < buttons.length; j++) {
      b = buttons[j];
      p = b.getAttribute('data-process');
      active = !type || p === type;
      b.style.opacity = active ? '1' : '0.4';
      bg = b.querySelector('.sp-ch-bg');
      if (bg) {
        bg.setAttribute('stroke-width', (type && p === type) ? '2.5' : '1.5');
        bg.setAttribute('fill', (type && p === type) ? '#F8FAFC' : '#FFFFFF');
      }
    }
  }

  for (var k = 0; k < buttons.length; k++) {
    buttons[k].addEventListener('click', function() {
      highlight(this.getAttribute('data-process'));
    });
  }
  if (reset) reset.addEventListener('click', function() { highlight(null); });
  document.addEventListener('keydown', function(e) {
    if (e.key === 'Escape') highlight(null);
  });
})();
